function splitAmounts(service,tip,terms){const percent=terms.mode==='rent'?100:Number(terms.barberPercent),barberService=Math.round(service*percent/100);return {barber:barberService+tip,shop:service-barberService,barberService,tip};}
function splitPanel(){const owner=state.role==='Owner HQ',id=owner?(state.splitBarber||activeBarberId()):activeBarberId(),b=barbers.find(b=>b.id===id)||activeStaff(),t=extras.chairTerms[b.id],rental=t.mode==='rent',percent=rental?100:Number(t.barberPercent),a=splitAmounts(10000,2000,t);return `<section class="panel split-panel"><div class="row between"><h2>${owner?'Team earnings split':'Your earnings split'}</h2><span class="finance-active">${rental?'Chair rental':'Commission active'}</span></div>${owner?`<label class="field">Team member<select id="split-barber">${barbers.map(x=>`<option value="${x.id}" ${x.id===b.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`:`<p class="muted">Set by your shop · ${esc(b.name)}</p>`}<form id="split-settings" data-barber="${b.id}">${owner?`<label class="field">Agreement<select name="mode"><option value="split" ${!rental?'selected':''}>Commission split</option><option value="rent" ${rental?'selected':''}>Chair rental</option></select></label>`:''}<div class="split-commission-fields" ${rental?'hidden':''}><div class="split-labels"><span><strong id="split-barber-value">${percent}%</strong> Barber</span><span><strong id="split-owner-value">${100-percent}%</strong> Shop</span></div><div class="split-meter"><span id="split-meter-fill" style="width:${percent}%"></span></div>${owner?`<label class="block-slider"><span>Barber share <output id="split-slider-value">${percent}%</output></span><input type="range" name="barberPercent" min="0" max="100" step="1" value="${percent}" aria-label="Barber share percentage"></label>`:''}</div><div class="split-rental-fields" ${!rental?'hidden':''}><div class="notice">The barber keeps service revenue and tips. Chair rent is tracked separately.</div>${owner?`<label class="field">Chair rent ($)<input type="number" name="rent" min="0" step="0.01" value="${t.amount||0}"></label><label class="field">Frequency<select name="period">${['day','week','month'].map(p=>`<option value="${p}" ${t.period===p?'selected':''}>Per ${p}</option>`).join('')}</select></label>`:`<p>${money(t.amount)} per ${t.period}</p>`}</div><div class="split-example"><small>$100 service + $20 tip</small><div><span>Barber receives</span><strong id="split-example-barber">${cents(a.barber)}</strong></div><div><span>Shop receives</span><strong id="split-example-shop">${cents(a.shop)}</strong></div></div><p class="split-note">Tips go 100% to the barber. Split shown before processing fees.</p>${owner?'<button class="btn">Save earnings agreement</button><p id="split-saved" role="status"></p>':''}</form></section>`;}
const settingsBeforeSplit=financeSettings;financeSettings=function(){return splitPanel()+settingsBeforeSplit();};
const overviewBeforeSplit=financeOverview;financeOverview=function(){return overviewBeforeSplit()+splitPanel();};
function splitPaymentRows(){const owner=state.role==='Owner HQ',actual=bookings.filter(b=>b.ticket?.approval&&b.status!=='cancelled'&&(owner?b.location===extras.location:b.barber===activeBarberId())).map(b=>({client:b.client,barber:b.barber,service:b.ticket.approval.subtotalCents,tip:b.ticket.approval.tipCents,date:b.date,total:b.ticket.approval.totalCents,paid:b.settlement?.status==='paid'}));return actual.length?actual:[{client:'John B.',barber:'alex',service:3200,tip:2000,date:today,total:5200,paid:true},{client:'Alex Morgan',barber:'alex',service:4000,tip:1500,date:today,total:5500,paid:true},{client:'Ryan Smith',barber:owner?'jordan':activeBarberId(),service:4000,tip:800,date:today,total:4800,paid:true}];}
financePayments=function(){const records=splitPaymentRows();return `<section class="panel finance-history"><h2>Payments & earnings</h2>${records.map(p=>{const t=extras.chairTerms[p.barber]||{mode:'split',barberPercent:60},a=splitAmounts(p.service,p.tip,t),name=barbers.find(b=>b.id===p.barber)?.name||'Barber';return `<article class="split-payment"><div class="finance-payment-row">${clientPhoto(p.client)}<span class="details"><strong>${esc(p.client)}</strong><small>${pretty(p.date)} · ${esc(name)} · ${cents(p.service)} service + ${cents(p.tip)} tip</small></span><strong>${cents(p.total)}</strong><span class="finance-paid">${p.paid?'Paid':'Approved'}</span></div><div class="split-payment-shares"><span><small>Barber ${t.mode==='rent'?'100':t.barberPercent}% + tip</small><strong>${cents(a.barber)}</strong></span><span><small>Shop ${t.mode==='rent'?0:100-t.barberPercent}%</small><strong>${cents(a.shop)}</strong></span></div></article>`;}).join('')}</section>`;};
function payoutMethods(w=financeWallet()){if(!w.methods)w.methods=[...(w.bank?[{id:'bank-original',kind:'bank',label:w.bank}]:[]),...(w.instant?[{id:'card-original',kind:'instant',label:w.instant}]:[])];return w.methods;}
function updatePayoutDefaults(w){const methods=payoutMethods(w);if(!methods.some(m=>m.kind==='bank'&&m.label===w.bank))w.bank=methods.find(m=>m.kind==='bank')?.label||'';if(!methods.some(m=>m.kind==='instant'&&m.label===w.instant))w.instant=methods.find(m=>m.kind==='instant')?.label||'';}
financeBankDialog=function(){const w=financeWallet();payoutMethods(w);const d=financeDialog(`<div class="row between"><h2>Payout methods</h2><button class="icon-btn" data-finance-close aria-label="Close">${icon('close')}</button></div><div id="payout-method-list"></div><form id="add-payout-method"><h3>Add payout method</h3><label class="field">Method<select name="kind"><option value="bank">Bank account</option><option value="instant">⚡ Debit card · instant payouts · 1.5%</option></select></label><label class="field">Account label<input name="label" maxlength="35" placeholder="e.g. Chase checking" required></label><label class="field">Last four digits<input name="last4" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" placeholder="1100" required></label><p class="connect-error" role="alert"></p><button class="btn full">${icon('plus')} Add method</button></form>`);const draw=()=>{d.querySelector('#payout-method-list').innerHTML=payoutMethods(w).map(m=>`<div class="payout-managed-row"><span class="finance-row-icon">${icon(m.kind==='instant'?'lightning':'card')}</span><div><strong>${esc(m.label)}</strong><small>${m.kind==='instant'?'Instant payouts · 1.5% fee':'Bank transfers'}${(m.kind==='bank'?w.bank:w.instant)===m.label?' · Default':''}</small><div class="payout-method-actions"><button class="text-btn" data-payout-default="${m.id}">Make default</button><button class="text-btn" data-payout-delete="${m.id}">Remove</button></div></div></div>`).join('')||'<p class="muted">No payout methods. Add one below.</p>';};draw();d.addEventListener('click',e=>{const remove=e.target.closest('[data-payout-delete]'),pick=e.target.closest('[data-payout-default]');if(remove){w.methods=w.methods.filter(m=>m.id!==remove.dataset.payoutDelete);updatePayoutDefaults(w);save();draw();render();}if(pick){const m=w.methods.find(m=>m.id===pick.dataset.payoutDefault);if(!m)return;w[m.kind==='bank'?'bank':'instant']=m.label;save();draw();render();}});d.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),kind=String(f.get('kind')),label=String(f.get('label')).trim(),last4=String(f.get('last4'));if(!['bank','instant'].includes(kind)||!label||!/^\d{4}$/.test(last4)){d.querySelector('[role=alert]').textContent='Add a label and exactly four digits.';return;}const display=label+' •• '+last4;if(w.methods.some(m=>m.label===display)){d.querySelector('[role=alert]').textContent='That method is already saved.';return;}w.methods.push({id:crypto.randomUUID(),kind,label:display});if(!w[kind==='bank'?'bank':'instant'])w[kind==='bank'?'bank':'instant']=display;save();e.target.reset();draw();render();toast('Payout method added.');});};
const financeSettingsWithSplits=financeSettings;financeSettings=function(){const w=financeWallet();payoutMethods(w);return financeSettingsWithSplits().replace(/<h2>Payout destinations<\/h2>/,'<div class="row between"><h2>Payout methods</h2><button class="text-btn" data-finance="bank">Manage / add</button></div>').replace(icon('wallet'),icon('lightning')).replace('Debit card · instant payouts',icon('lightning')+' ⚡ Debit card · instant payouts · 1.5% fee').replace('Bank account · standard payouts','Bank account · standard payouts').replace('>Verified</span>','>'+(w.bank?'Verified':'Add account')+'</span>').replace('>Ready</span>','>'+(w.instant?'Ready':'Add card')+'</span>');};
function profileLink(id=activeBarberId()){const slug={alex:'lara',jordan:'jose',watkins:'watkins'}[id]||id;return location.origin+'/app/?barber='+encodeURIComponent(slug)+'&store='+encodeURIComponent(extras.location||'scottsdale');}
function shareProfileCard(id){return `<section class="panel share-profile-card"><span class="finance-row-icon">${icon('share')}</span><h2>Your chair. One link.</h2><p class="muted">Share your profile in your bio, in a message or wherever clients find you.</p><label class="field">Your booking link<input readonly id="barber-share-link" value="${esc(profileLink(id))}" aria-label="Public barber profile link"></label><div class="finance-actions"><button class="btn" data-profile-share="${id}">${icon('share')} Share profile</button><button class="btn secondary" data-profile-copy="${id}">Copy link</button></div><p id="profile-share-status" role="status"></p></section>`;}
