const proProfileBeforeSharing=proProfile;proProfile=function(){return shareProfileCard(activeBarberId())+proProfileBeforeSharing();};
async function copyBarberLink(id){const url=profileLink(id);try{await navigator.clipboard.writeText(url);}catch{const input=document.createElement('textarea');input.value=url;input.style.position='fixed';input.style.opacity='0';document.body.append(input);input.select();const copied=document.execCommand('copy');input.remove();if(!copied)throw Error('Select and copy the profile link above.');}const status=document.querySelector('#profile-share-status');if(status)status.textContent='Link copied. Ready for your bio.';toast('Profile link copied.');}
document.addEventListener('click',async e=>{const share=e.target.closest('[data-profile-share]'),copy=e.target.closest('[data-profile-copy]');if(!share&&!copy)return;const id=(share||copy).dataset[share?'profileShare':'profileCopy'];try{if(share&&navigator.share){await navigator.share({title:(barbers.find(b=>b.id===id)?.name||'Your barber')+' at Hairflix',text:'See my work and book your next visit.',url:profileLink(id)});}else await copyBarberLink(id);}catch(err){if(err.name!=='AbortError')toast(err.message);}});
document.addEventListener('change',e=>{if(e.target.id==='split-barber'){state.splitBarber=e.target.value;render();}if(e.target.matches('#split-settings [name=mode]')){const form=e.target.form,rent=e.target.value==='rent';form.querySelector('.split-commission-fields').hidden=rent;form.querySelector('.split-rental-fields').hidden=!rent;updateSplitExample(form);}});
function updateSplitExample(form){const rent=form.querySelector('[name=mode]')?.value==='rent',percent=rent?100:Number(form.querySelector('[name=barberPercent]')?.value||60),a=splitAmounts(10000,2000,{mode:rent?'rent':'split',barberPercent:percent});for(const [id,value] of [['split-barber-value',percent+'%'],['split-owner-value',(100-percent)+'%'],['split-slider-value',percent+'%'],['split-example-barber',cents(a.barber)],['split-example-shop',cents(a.shop)]]){const el=form.querySelector('#'+id);if(el)el.textContent=value;}form.querySelector('#split-meter-fill').style.width=percent+'%';}
document.addEventListener('input',e=>{if(e.target.matches('#split-settings [name=barberPercent]'))updateSplitExample(e.target.form);});
document.addEventListener('submit',e=>{if(e.target.id!=='split-settings')return;e.preventDefault();if(state.role!=='Owner HQ')return;const f=new FormData(e.target),id=e.target.dataset.barber,t=extras.chairTerms[id],percent=Number(f.get('barberPercent'));if(!Number.isInteger(percent)||percent<0||percent>100||!['split','rent'].includes(String(f.get('mode')))||!Number.isFinite(Number(f.get('rent')||0))||Number(f.get('rent')||0)<0||Number(f.get('rent')||0)>100000)return;extras.chairTerms[id]={...t,mode:String(f.get('mode')),barberPercent:percent,amount:Number(f.get('rent')||0),period:String(f.get('period')||'week')};save();render();toast('Earnings agreement saved.');});
function closedEarningsSummary(){const list=state.role==='Owner HQ'?ownerScopeBookings():bookings.filter(b=>b.barber===activeBarberId());return list.filter(b=>b.date===state.calendarDate&&b.status!=='cancelled'&&b.ticket?.approval&&b.settlement?.status==='paid'&&b.settlement.amountCents===b.ticket.approval.totalCents).reduce((total,b)=>{const a=b.ticket.approval,s=splitAmounts(a.subtotalCents,a.tipCents,extras.chairTerms[b.barber]);total.gross+=a.totalCents;total.barber+=s.barber;total.shop+=s.shop;total.tips+=a.tipCents;return total;},{gross:0,barber:0,shop:0,tips:0});}
function closedSplitCard(){const s=closedEarningsSummary(),owner=state.role==='Owner HQ';return `<section class="panel closed-split-card"><div><span>${owner?'Shop share today':'Your take-home today'}</span><strong>${cents(owner?s.shop:s.barber)}</strong></div><div class="closed-split-details"><span>Closed payments <strong>${cents(s.gross)}</strong></span><span>${owner?'Barbers + tips':'Shop share'} <strong>${cents(owner?s.barber:s.shop)}</strong></span><small>Tips stay with the barber · before processing fees</small></div></section>`;}
function cleanProductText(root){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){if(node.parentElement?.closest('script,style,textarea'))continue;let text=node.textContent;text=text.replace(/\b(?:for )?(?:demo|demonstration|illustrative) purposes(?: only)?\.?/gi,'').replace(/Fictional demo barber/gi,'Barber').replace(/\bfictional\s+/gi,'').replace(/\bdemo\s*/gi,'').replace(/\billustrative\s*/gi,'').replace(/\bfor illustration(?: purposes)?\b/gi,'').replace(/\bfor illustrative purposes\b/gi,'');if(text!==node.textContent)node.textContent=text;}}
const renderBeforeFinishing=render;render=function(){renderBeforeFinishing();if(isStaff()&&state.view==='home')document.querySelector(state.role==='Owner HQ'?'.owner-summary':'.barber-summary')?.insertAdjacentHTML('afterend',closedSplitCard());if(state.role==='Owner HQ'&&state.view==='hMember')document.querySelector('main')?.insertAdjacentHTML('beforeend',shareProfileCard(state.member||activeBarberId()));if(state.role==='Customer'&&state.view==='cBarberProfile')document.querySelector('.customer-profile-actions')?.insertAdjacentHTML('beforeend',`<button class="btn secondary" data-profile-share="${state.barber}">${icon('share')} Share</button>`);if(state.role==='Owner HQ'&&state.view==='businessSettings'){const forms=[...document.querySelectorAll('.chair-terms-form')];if(forms.length){forms[0].insertAdjacentHTML('beforebegin',splitPanel());forms.forEach(f=>f.remove());}}if(isStaff()){document.querySelectorAll('[data-finance=bank] .details strong').forEach(el=>{if(!el.textContent.trim())el.textContent='Add payout method';});}cleanProductText(document.querySelector('#app'));};
const productTextObserver=new MutationObserver(records=>{for(const r of records)for(const node of r.addedNodes)if(node.nodeType===1&&!node.matches('script,style'))cleanProductText(node);else if(node.nodeType===3&&node.parentElement&&!node.parentElement.closest('script,style,textarea'))cleanProductText(node.parentElement);});productTextObserver.observe(document.body,{childList:true,subtree:true});
